export const b2Objectives = defineObjectives("b2", [
  [1,"gram","g128","Imperfecto de subjuntivo: formas -ra y -se","Puedo formar el imperfecto de subjuntivo en -ra y en -se a partir de la tercera persona plural del pretérito, con sus irregularidades, y usarlo en deseos difíciles con «ojalá» y en peticiones corteses con «quisiera».",["b1.gram.g088"],{"related":["/sistema-verbal/preterito-imperfecto-subjuntivo"]}],
  [1,"gram","g129","Subjuntivo tras verbos de influencia en pasado","Puedo contar lo que alguien pidió, quiso, prohibió o lamentó en el pasado con «que + imperfecto de subjuntivo», usar infinitivo cuando el sujeto es el mismo y distinguir información de petición con «decir» o «insistir».",["b2.gram.g128","b1.gram.g090"],{"related":["/gramatica/subjuntivo-tras-verbos-de-influencia-en"]}],
  [1,"voc","w01-negocio-familiar","Negocio familiar y patrimonio del barrio","Puedo hablar de la herencia y la reforma de un negocio familiar con colocaciones como «hacerse cargo del local», «conservar el mobiliario» o «dar el visto bueno».",["b2.gram.g129"]],
  [1,"pron","w01-acento-ra","Acento de las formas en -ra","Puedo distinguir de oído «conservara» y «conservará» y pronunciar con acento esdrújulo las formas de «nosotros»: «conserváramos», «tuviéramos».",["b2.gram.g128"]],
  [1,"lis","w01-reunion-familiar","Reunión familiar sobre un legado","Puedo seguir una conversación entre hermanos que recuerdan lo que su abuela les pidió y reconstruir qué encargo ya se cumplió y cuál sigue pendiente.",["b2.gram.g129"]],
  [1,"read","w01-cronica-reapertura","Crónica de barrio sobre una reapertura","Puedo leer una crónica de una revista de barrio e identificar qué deseos y peticiones se atribuyen a cada persona y qué opina la autora.",["b2.gram.g129"]],
  [1,"wri","w01-correo-decisiones","Correo que transmite encargos","Puedo escribir un correo de más de 200 palabras que cuente a un familiar lejano lo que se pidió y se decidió en una reunión, separando hechos, peticiones y opiniones.",["b2.gram.g129","b2.disc.w01-relato-encargos"]],
  [1,"spk","w01-relatar-encargos","Contar encargos y negociar su cumplimiento","Puedo contar en dos minutos lo que una persona importante esperaba de mí y negociar con alguien que interpreta ese encargo de otra manera.",["b2.fun.w01-transmitir-peticiones"]],
  [1,"fun","w01-transmitir-peticiones","Transmitir peticiones y deseos ajenos","Puedo transmitir lo que otra persona pidió, prohibió o quería, y aclarar si la petición ya se cumplió o sigue vigente.",["b2.gram.g129"]],
  [1,"disc","w01-relato-encargos","Atribuir y ordenar un relato de encargos","Puedo organizar un relato que atribuye cada petición a su autor, la sitúa en el tiempo y marca después mi propia valoración.",["b2.gram.g129"]],
  [2,"gram","g130","Correlación temporal: presente, pasado y futuro","Puedo elegir entre «presente», «imperfecto» y «perfecto de subjuntivo» según el tiempo del verbo principal y el momento de la acción, también detrás de «cuando» y «para que».",["b2.gram.g128","b2.gram.g129"],{"related":["/gramatica/correlacion-temporal-presente-pasado-y-futuro"]}],
  [2,"gram","g131","Si + imperfecto de subjuntivo + condicional","Puedo distinguir un plan posible («si ganamos, empezaremos») de una situación imaginada («si ganáramos, empezaríamos») y negociar opciones sin poner futuro ni condicional después de «si».",["b2.gram.g128","b1.gram.g102"],{"related":["/si-fuera-distinto"]}],
  [2,"voc","w02-participacion-vecinal","Participación vecinal y presupuesto participativo","Puedo hablar de un proyecto de barrio con expresiones como «presentar una propuesta», «someter a votación», «reunir firmas» o «ejecutar una obra».",["b2.gram.g131"]],
  [2,"pron","w02-presente-imperfecto-subj","Oír el tiempo del subjuntivo","Puedo distinguir de oído «presentemos» y «presentáramos» y entonar una oración con «si» con una subida antes de la coma y un descenso en la consecuencia.",["b2.gram.g130"]],
  [2,"lis","w02-entrevista-radio","Entrevista en una radio local","Puedo seguir una entrevista radial sobre un proyecto vecinal y distinguir lo que ya se pidió, lo que se espera y lo que solo se imagina.",["b2.gram.g130","b2.gram.g131"]],
  [2,"read","w02-boletin-vecinal","Boletín de una vecinal","Puedo leer el boletín de una asociación vecinal y separar los requisitos oficiales, los planes posibles y las hipótesis de sus autores.",["b2.gram.g131"]],
  [2,"wri","w02-propuesta-municipio","Propuesta formal al municipio","Puedo escribir una propuesta de más de 200 palabras que presente un proyecto, recuerde lo que pidió la administración y plantee qué se haría en distintos escenarios.",["b2.gram.g130","b2.disc.w02-marco-temporal"]],
  [2,"spk","w02-defender-proyecto","Defender un proyecto ante el barrio","Puedo defender oralmente un proyecto vecinal, plantear escenarios hipotéticos y negociar con alguien que prefiere otra opción.",["b2.fun.w02-plantear-hipotesis"]],
  [2,"fun","w02-plantear-hipotesis","Plantear escenarios y negociar opciones","Puedo proponer con prudencia, imaginar consecuencias y marcar si veo una condición posible o lejana.",["b2.gram.g131"]],
  [2,"disc","w02-marco-temporal","Mantener el marco temporal de un texto","Puedo mantener coherente el marco temporal de un texto y cambiarlo de forma explícita cuando paso del relato pasado a la petición actual.",["b2.gram.g130"]],
  [3,"gram","g132","Condiciones del pasado y resultados alternativos","Puedo imaginar otro final para un hecho pasado con «si + hubiera + participio» y «habría + participio», anclando bien en el tiempo la condición y el resultado.",["b2.gram.g131"],{"related":["/condicionales"]}],
  [3,"gram","g133","Pluscuamperfecto de subjuntivo: pasado no realizado","Puedo formar «hubiera / hubiese + participio» y usarlo para reaccionar en pasado a algo anterior, para condiciones pasadas no cumplidas y para lamentar con «ojalá».",["b2.gram.g128","b2.gram.g130"],{"related":["/sistema-verbal/preterito-pluscuamperfecto-subjuntivo"]}],
  [3,"voc","w03-competicion-remo","Competición, entrenamiento y estrategia","Puedo hablar de una competición y de sus decisiones con expresiones como «perder por centímetros», «cambiar la estrategia» o «sacar conclusiones».",["b2.gram.g132"]],
  [3,"pron","w03-habia-habria","«Había» y «habría»; enlace de auxiliar y participio","Puedo distinguir de oído «había ganado» y «habría ganado» y pronunciar enlazados el auxiliar y el participio: «hubiera_ido», «habría_entrenado».",["b2.gram.g133"]],
  [3,"lis","w03-analisis-regata","Análisis después de una regata","Puedo seguir una conversación entre una entrenadora y dos remeros que revisan una final perdida y separar lo que pasó, lo que habría pasado y lo que lamentan.",["b2.gram.g132","b2.gram.g133"]],
  [3,"read","w03-carta-entrenadora","Carta de una entrenadora al equipo","Puedo leer una carta que analiza una temporada e identificar las alternativas que plantea, las reacciones a hechos anteriores y la lección final.",["b2.gram.g133"]],
  [3,"wri","w03-informe-lecciones","Informe de lecciones aprendidas","Puedo escribir un informe de más de 200 palabras sobre un proyecto o una competición que salió mal, con hechos, alternativas razonadas y propuestas, sin buscar culpables.",["b2.gram.g132","b2.disc.w03-hecho-alternativa"]],
  [3,"spk","w03-revisar-decision","Revisar una decisión en grupo","Puedo analizar oralmente una decisión pasada, imaginar otro resultado y responder con calma a alguien que me la reprocha.",["b2.fun.w03-analizar-decisiones"]],
  [3,"fun","w03-analizar-decisiones","Analizar decisiones pasadas y lamentar","Puedo explicar qué habría pasado con otra decisión, reaccionar a lo que otros habían hecho y expresar arrepentimiento sin dramatizar.",["b2.gram.g133"]],
  [3,"disc","w03-hecho-alternativa","Del hecho a la alternativa y a la lección","Puedo organizar un análisis en tres pasos: lo que ocurrió, lo que habría ocurrido con otra decisión y lo que haremos ahora.",["b2.gram.g132"]],
  [4,"gram","g134","Condicional compuesto: hipótesis y reproches","Puedo usar «habría + participio» para un resultado que no ocurrió, para un futuro terminado visto desde el pasado y para reprochar con suavidad con «habrías podido» o «habrías debido».",["b2.gram.g132","b2.gram.g133"],{"related":["/sistema-verbal/condicional-compuesto-indicativo"]}],
  [4,"gram","g135","Condicionales mixtas: pasado y consecuencia presente","Puedo explicar cómo sería hoy mi vida con otra decisión pasada («si me hubiera quedado, ahora viviría…») y cómo un rasgo actual cambió lo que pasó («si fuera más paciente, no habría discutido»).",["b2.gram.g131","b2.gram.g133","b2.gram.g134"],{"related":["/gramatica/condicionales-mixtas-pasado-y-consecuencia-presente"]}],
  [4,"voc","w04-mudanza-obra","Mudanzas, obras y decisiones de vida","Puedo hablar de una mudanza y de una reforma con expresiones como «echar raíces», «el plazo de entrega», «cumplir lo prometido» o «valer la pena».",["b2.gram.g135"]],
  [4,"pron","w04-reproche-suave","Entonación del reproche atenuado","Puedo reconocer por la entonación si «habrías podido avisar» es un reproche suave o una simple hipótesis, y decir un reproche sin sonar agresivo.",["b2.gram.g134"]],
  [4,"lis","w04-podcast-decisiones","Podcast sobre decisiones de vida","Puedo seguir una entrevista de un podcast en la que alguien explica cómo una decisión pasada cambió su presente y separar hechos, hipótesis y reproches.",["b2.gram.g135"]],
  [4,"read","w04-blog-regreso","Entrada de blog sobre un regreso","Puedo leer una entrada de blog personal e identificar qué causas pasadas explican la situación actual de la autora y qué habría sido distinto.",["b2.gram.g134","b2.gram.g135"]],
  [4,"wri","w04-reclamo-cortes","Reclamo formal y cortés","Puedo escribir un reclamo de más de 200 palabras a una empresa que no cumplió un plazo, con reproches atenuados, consecuencias presentes y una petición concreta.",["b2.gram.g134","b2.disc.w04-pasado-presente"]],
  [4,"spk","w04-otra-vida","Imaginar otra vida","Puedo contar cómo sería mi vida hoy si hubiera tomado otra decisión y responder a preguntas sobre esa versión imaginada.",["b2.gram.g135"]],
  [4,"fun","w04-reprochar-atenuar","Reprochar con suavidad y responder","Puedo señalar lo que alguien habría podido hacer sin sonar agresivo y responder a un reproche reconociendo o matizando.",["b2.gram.g134"]],
  [4,"disc","w04-pasado-presente","Unir causas pasadas y consecuencias presentes","Puedo organizar un texto que relaciona hechos pasados con su efecto actual usando «hoy», «todavía», «ya no» y condicionales mixtas.",["b2.gram.g135"]],
  [5,"gram","g239","Condiciones con otros nexos","Puedo poner condiciones con «siempre que», «con tal de que», «a no ser que», «en caso de que» o «por si», eligiendo modo, matiz y registro, y distinguir «siempre que» condicional de «cada vez que».",["b2.gram.g130","b2.gram.g131"],{"related":["/gramatica/condiciones-con-otros-nexos"]}],
  [5,"gram","g136","Como si + imperfecto / pluscuamperfecto subjuntivo","Puedo describir cómo actúa alguien comparándolo con algo imaginado, simultáneo («como si fuera el dueño») o anterior («como si no hubiera pasado nada»), y reaccionar con «¡ni que…!».",["b2.gram.g128","b2.gram.g133"],{"related":["/gramatica/como-si-imperfecto-pluscuamperfecto-subjuntivo"]}],
  [5,"voc","w05-alquiler-convivencia","Alquiler y convivencia compartida","Puedo hablar de un alquiler compartido con expresiones como «el depósito», «repartir los gastos», «dar aviso con un mes de anticipación» o «hacerse cargo de la limpieza».",["b2.gram.g239"]],
  [5,"pron","w05-nexos-pausa","Grupos fónicos con nexos largos","Puedo pronunciar «siempre y cuando», «a no ser que» o «como si» como un solo bloque, sin pausa en el medio, y hacer la pausa antes del nexo.",["b2.gram.g239"]],
  [5,"lis","w05-reunion-convivencia","Reunión de compañeros de departamento","Puedo seguir una reunión de tres estudiantes que negocian normas de convivencia y reconstruir cada condición, cada queja y lo que acuerdan.",["b2.gram.g239","b2.gram.g136"]],
  [5,"read","w05-guia-convivencia","Guía para compartir vivienda","Puedo leer una guía universitaria sobre alquileres compartidos y relacionar cada norma con su condición, su excepción y los casos que la ilustran.",["b2.gram.g239"]],
  [5,"wri","w05-acuerdo-convivencia","Propuesta de acuerdo de convivencia","Puedo escribir una propuesta de más de 220 palabras que recuerde lo que pasó, ponga condiciones claras con distintos nexos e imagine qué habría pasado y qué pasaría con otras reglas.",["b2.gram.g239","b2.disc.w05-normas-condiciones"]],
  [5,"spk","w05-negociar-condiciones","Negociar las condiciones de un alquiler","Puedo negociar oralmente las condiciones de un alquiler, aceptar con matices, proponer excepciones y describir comportamientos con «como si».",["b2.fun.w05-poner-condiciones"]],
  [5,"fun","w05-poner-condiciones","Poner condiciones, excepciones y avisos","Puedo aceptar algo bajo condición, señalar una excepción, prever un caso y advertir en tono coloquial con «como + subjuntivo».",["b2.gram.g239"]],
  [5,"disc","w05-normas-condiciones","Organizar normas con condiciones","Puedo organizar un texto normativo breve en el que cada norma va acompañada de su condición, su excepción y su consecuencia.",["b2.gram.g239"]],
  [5,"rev","w05-integrar-semanas-1-4","Integración: subjuntivo y condiciones de las semanas 1 a 4","Puedo combinar en un mismo texto peticiones en pasado, correlación de tiempos, hipótesis presentes y pasadas, reproches con «habría» y condicionales mixtas.",["b2.gram.g128","b2.gram.g129","b2.gram.g130","b2.gram.g131","b2.gram.g132","b2.gram.g133","b2.gram.g134","b2.gram.g135"]],
  [6,"gram","g137","Concesión: aunque + indicativo / subjuntivo","Puedo elegir indicativo o subjuntivo después de «aunque» según presente un dato nuevo, una objeción que ya se conoce o una posibilidad abierta, y mantener mi postura sin cambiar de idea.",[],{"related":["/aunque-cambie-el-dato"]}],
  [6,"gram","g138","A pesar de que, por mucho que, por más que","Puedo conceder con más fuerza con «a pesar de que», «por mucho que», «por más que», «por muy… que», «si bien» y «aun cuando», eligiendo modo, intensidad y registro.",["b2.gram.g137"],{"related":["/gramatica/a-pesar-de-que-por-mucho"]}],
  [6,"voc","w06-agua-vinedo","Agua, riego y viñedo","Puedo hablar con precisión de la escasez de agua y de la gestión de una finca: turno de riego, riego por goteo, cupo, cosecha, rinde, poner en marcha una inversión.",["b2.gram.g137"]],
  [6,"pron","w06-modo-al-oido","Oír el modo y la pausa concesiva","Puedo distinguir de oído «aunque sube» y «aunque suba» por la vocal final y marcar con la voz la pausa entre la concesión y la decisión.",["b2.gram.g137"]],
  [6,"lis","w06-reunion-finca","Reunión familiar en una finca","Puedo seguir una reunión en la que una familia discute una inversión y reconstruir qué objeciones aceptan y qué decisión mantienen.",["b2.gram.g137","b2.gram.g138"]],
  [6,"read","w06-columna-agua","Columna de opinión sobre el agua","Puedo leer una columna de opinión que concede argumentos contrarios y separar lo que el autor admite de lo que sostiene.",["b2.gram.g138"]],
  [6,"wri","w06-carta-asamblea","Carta a la asamblea de una cooperativa","Puedo escribir una carta de más de 200 palabras que reconozca las objeciones de otros socios y defienda una propuesta con conectores concesivos variados.",["b2.gram.g138","b2.disc.w06-orden-registro"]],
  [6,"spk","w06-sostener-postura","Sostener una postura ante objeciones","Puedo responder oralmente a objeciones insistentes, concediendo lo razonable y manteniendo mi decisión con argumentos.",["b2.fun.w06-conceder-mantener"]],
  [6,"fun","w06-conceder-mantener","Conceder y mantener una decisión","Puedo aceptar una objeción, ponerle un límite y mantener mi plan sin sonar cerrado ni agresivo.",["b2.gram.g137"]],
  [6,"disc","w06-orden-registro","Posición y registro de la concesión","Puedo colocar la concesión delante o detrás según quiera preparar o matizar mi conclusión, y elegir entre «aunque», «si bien» o «aun cuando» según el registro.",["b2.gram.g138"]],
  [7,"gram","g139","Temporales con subjuntivo para futuro incierto","Puedo hablar de lo que pasará cuando ocurra algo incierto con «cuando», «en cuanto», «tan pronto como», «una vez que», «hasta que» o «antes de que» + subjuntivo, también desde el pasado («en cuanto llegara»), y usar el infinitivo cuando el sujeto es el mismo.",["b2.gram.g128"],{"related":["/gramatica/temporales-con-subjuntivo-para-futuro-incierto"]}],
  [7,"gram","g140","Finales con subjuntivo: con el fin de que, sin que","Puedo explicar para qué se hace algo y qué se quiere evitar con «para que», «con el fin de que», «a fin de que», «sin que» y «no vaya a ser que», ajustando el tiempo del subjuntivo al verbo principal.",["b2.gram.g128"],{"related":["/gramatica/finales-con-subjuntivo-con-el-fin"]}],
  [7,"voc","w07-sismo-simulacro","Sismos, evacuación y simulacros","Puedo usar el léxico de la prevención sísmica y de un simulacro escolar: réplica, punto de encuentro, zona segura, mochila de emergencia, alerta, pasar lista.",["b2.gram.g139"]],
  [7,"pron","w07-bloques-conectores","Conectores como un solo bloque","Puedo pronunciar «en cuanto», «tan pronto como», «a fin de que» o «no vaya a ser que» como un solo grupo fónico, enlazando las palabras sin pausas internas.",["b2.gram.g139","b2.gram.g140"]],
  [7,"lis","w07-reunion-simulacro","Reunión para preparar un simulacro","Puedo seguir una reunión de preparación de un simulacro y reconstruir qué pasará en cada momento y para qué se toma cada medida.",["b2.gram.g139","b2.gram.g140"]],
  [7,"read","w07-boletin-escuela","Boletín escolar sobre un protocolo","Puedo leer un artículo de boletín escolar que explica un protocolo y relacionar cada paso con su momento y su finalidad.",["b2.gram.g139","b2.gram.g140"]],
  [7,"wri","w07-correo-familias","Correo informativo a las familias","Puedo escribir un correo de más de 200 palabras que informe a las familias de un plan futuro, ordene los pasos en el tiempo y explique la finalidad de cada medida.",["b2.gram.g140","b2.disc.w07-secuencia-finalidad"]],
  [7,"spk","w07-explicar-protocolo","Explicar un protocolo y tranquilizar","Puedo explicar oralmente qué hay que hacer en cada momento de una emergencia y responder a las preguntas de alguien preocupado.",["b2.fun.w07-planificar-prevenir"]],
  [7,"fun","w07-planificar-prevenir","Planificar y prevenir","Puedo anunciar lo que haré cuando se cumpla una condición incierta y explicar qué quiero conseguir o evitar con cada medida.",["b2.gram.g139","b2.gram.g140"]],
  [7,"disc","w07-secuencia-finalidad","Secuencia temporal y finalidad en instrucciones","Puedo organizar instrucciones de modo que cada paso tenga un momento claro («en cuanto», «una vez que») y una finalidad explícita («para que», «a fin de que»).",["b2.gram.g139","b2.gram.g140"]],
  [8,"gram","g141","Subordinadas modales y comparativas irreales","Puedo decir cómo se hace algo con «como», «según» o «tal como» + indicativo si la manera es conocida o + subjuntivo si está abierta, y comparar con lo esperado («más de lo que pensaba», «menos lana de la que calculamos») o con lo imaginado («igual que si», «tanto como si»).",["b2.gram.g136"],{"related":["/gramatica/subordinadas-modales-y-comparativas-irreales"]}],
  [8,"gram","g142","Relativos con preposición: de quien, a quien, con el que","Puedo unir dos ideas con un relativo precedido de la preposición que pide el verbo («con la que», «del que», «a quien», «en el que») y con el artículo que concuerda con el antecedente.",["b1.gram.g100"],{"related":["/gramatica/relativos-con-preposicion"]}],
  [8,"voc","w08-telar-oficio","Telar, lana y oficio artesanal","Puedo hablar de un oficio artesanal y de su proceso: urdir, teñir con tintes naturales, el telar criollo, la trama, el encargo, la pieza única.",["b2.gram.g142"]],
  [8,"pron","w08-grupo-relativo","El grupo «preposición + relativo» sin acento propio","Puedo pronunciar «con la que», «de quien» o «en el que» como sílabas átonas unidas al verbo que sigue, sin cortar la frase después de la preposición.",["b2.gram.g142"]],
  [8,"lis","w08-taller-telar","Visita de una compradora a un taller","Puedo seguir la conversación entre artesanos y una compradora y reconstruir cómo se hace cada pieza, con qué materiales y de quién aprendieron.",["b2.gram.g141","b2.gram.g142"]],
  [8,"read","w08-reportaje-tejedoras","Reportaje sobre un oficio","Puedo leer un reportaje de revista sobre un oficio tradicional y distinguir lo que se hace como siempre, lo que se deja abierto y lo que superó las expectativas.",["b2.gram.g141","b2.gram.g142"]],
  [8,"wri","w08-quienes-somos","Presentación de un taller","Puedo escribir un texto de presentación de más de 200 palabras que explique quiénes forman un taller, de quién aprendieron, cómo trabajan y qué superó lo que esperaban.",["b2.gram.g142","b2.disc.w08-precisar-referentes"]],
  [8,"spk","w08-presentar-oficio","Presentar un oficio y negociar un encargo","Puedo presentar oralmente un oficio y negociar un encargo, acordando cómo se hará la pieza y aclarando lo que el cliente quiere.",["b2.fun.w08-describir-proceso"]],
  [8,"fun","w08-describir-proceso","Describir una manera de hacer y compararla","Puedo explicar cómo se hace algo, dejar una decisión abierta al otro y comparar el resultado con lo que se esperaba.",["b2.gram.g141"]],
  [8,"disc","w08-precisar-referentes","Precisar referentes con relativos","Puedo identificar con precisión personas, lugares y objetos en un texto con relativos preposicionales, evitando repeticiones y frases cortadas.",["b2.gram.g142"]],
  [9,"gram","g143","Cuyo/a/os/as y relativos de posesión","Puedo unir un nombre con lo que le pertenece mediante «cuyo, cuya, cuyos, cuyas», concordando con lo poseído y también detrás de una preposición, y reformularlo al hablar con «del que», «de quien» o dos frases, sin usar «que su».",["b2.gram.g142"],{"related":["/gramatica/cuyo-a-os-as-y-relativos"]}],
  [9,"gram","g144","Referentes abstractos: lo cual, lo que, aquello que","Puedo comentar un hecho entero con «…, lo que» o «…, lo cual», encadenar consecuencias con «por lo que» o «con lo cual» y hablar de ideas con «lo + adjetivo + que», «aquello que» y «eso de que».",["b1.gram.g113"],{"related":["/gramatica/referentes-abstractos-lo-cual-lo-que"]}],
  [9,"voc","w09-patrimonio-urbano","Patrimonio urbano y arquitectura","Puedo describir edificios y espacios históricos de una ciudad: la fachada, el trazado, la diagonal, el edificio protegido, la restauración, la placa conmemorativa.",["b2.gram.g143"]],
  [9,"pron","w09-pausa-comentario","La pausa antes de «lo cual» y «lo que»","Puedo marcar con una pausa y un leve cambio de tono el paso del hecho al comentario en «…, lo cual…» y distinguirlo de «lo que» sin pausa.",["b2.gram.g144"]],
  [9,"lis","w09-grabacion-audioguia","Grabación de una audioguía","Puedo seguir la conversación de un equipo que graba una audioguía y reconstruir qué problemas tuvieron, qué consecuencias trajeron y cómo presentan cada edificio.",["b2.gram.g143","b2.gram.g144"]],
  [9,"read","w09-guion-recorrido","Guion de un recorrido patrimonial","Puedo leer el guion de un recorrido por una ciudad y relacionar cada edificio con lo que le pertenece y cada hecho con el comentario que lo valora.",["b2.gram.g143","b2.gram.g144"]],
  [9,"wri","w09-ficha-patrimonio","Ficha de un edificio con historia","Puedo escribir una ficha de más de 200 palabras sobre un edificio o un lugar con historia, con relativos de posesión y comentarios encadenados sobre los hechos.",["b2.gram.g144","b2.disc.w09-encadenar-comentarios"]],
  [9,"spk","w09-guiar-recorrido","Guiar un recorrido y responder preguntas","Puedo guiar oralmente un recorrido breve, presentar cada lugar sin «que su» y responder a las preguntas de los visitantes comentando los hechos.",["b2.fun.w09-presentar-comentar"]],
  [9,"fun","w09-presentar-comentar","Presentar y comentar hechos","Puedo presentar a una persona o un lugar por lo que le pertenece y añadir un comentario o una consecuencia sobre un hecho completo.",["b2.gram.g143","b2.gram.g144"]],
  [9,"disc","w09-encadenar-comentarios","Encadenar hechos y comentarios","Puedo encadenar en un texto hechos, consecuencias y valoraciones con «lo cual», «por lo que» y «con lo cual», sin empezar una frase nueva para cada idea.",["b2.gram.g144"]],
  [10,"gram","g145","Antecedentes desconocidos: dondequiera que, cualquiera que","Puedo hablar de personas, lugares y cosas sin identificar con «cualquiera que», «quienquiera que», «dondequiera que», «cualquier… que», «pase lo que pase» o «sea cual sea», y elegir indicativo o subjuntivo en la relativa según el antecedente sea conocido, buscado o inexistente.",["b1.gram.g100"],{"related":["/gramatica/antecedentes-desconocidos-dondequiera-que-cualquiera-que"]}],
  [10,"gram","g146","Estilo indirecto: afirmaciones, preguntas, mandatos","Puedo transmitir lo que alguien afirmó, preguntó o pidió, desplazando los tiempos y las referencias de lugar y tiempo según el momento en que lo cuento y eligiendo un verbo que exprese la intención.",["b2.gram.g128"],{"related":["/gramatica/estilo-indirecto-transmitir"]}],
  [10,"voc","w10-playa-voluntariado","Playa, seguridad y voluntariado","Puedo hablar de la temporada de playa, de su seguridad y de un voluntariado ambiental: guardavidas, bandera roja, marea, resaca, limpieza de costa, residuos, turno, coordinadora.",["b2.gram.g145"]],
  [10,"pron","w10-voz-cita","Cambiar de voz entre cita y relato","Puedo marcar con la voz el paso de mis palabras a las palabras de otra persona y leer seguido «pase lo que pase» o «sea cual sea» como un solo bloque.",["b2.gram.g146"]],
  [10,"lis","w10-llamada-reunion","Llamada para contar una reunión","Puedo seguir una llamada en la que alguien cuenta lo que se dijo, se preguntó y se pidió en una reunión, y reconstruir las instrucciones y las condiciones.",["b2.gram.g145","b2.gram.g146"]],
  [10,"read","w10-cronica-temporada","Crónica de fin de temporada","Puedo leer una crónica periodística extensa que recoge declaraciones, concede objeciones y encadena hechos, y distinguir lo que dijo cada persona de lo que opina el autor.",["b2.gram.g146","b2.gram.g138","b2.gram.g144"]],
  [10,"wri","w10-acta-reunion","Resumen de una reunión para quien no estuvo","Puedo escribir un resumen de más de 200 palabras que transmita afirmaciones, preguntas y peticiones de una reunión y combine las estructuras de las semanas 6 a 10.",["b2.gram.g146","b2.disc.w10-transmitir-con-precision"]],
  [10,"spk","w10-transmitir-negociar","Transmitir instrucciones y negociar una norma","Puedo transmitir oralmente lo que se acordó en una reunión y negociar una norma con alguien que no está de acuerdo.",["b2.fun.w10-transmitir-mensajes"]],
  [10,"fun","w10-transmitir-mensajes","Transmitir mensajes de otros","Puedo contar lo que otra persona dijo, preguntó o pidió con verbos precisos (aclaró, advirtió, insistió en que) y adaptar tiempos y referencias.",["b2.gram.g146"]],
  [10,"disc","w10-transmitir-con-precision","Resumir sin perder matices","Puedo resumir lo que dijeron varias personas conservando sus concesiones, condiciones y finalidades, sin mezclar mi opinión con la suya.",["b2.gram.g146","b2.gram.g137","b2.gram.g140"]],
  [10,"rev","w10-integracion","Checkpoint: semanas 6 a 10","Puedo combinar en un mismo texto concesión, temporales y finales con subjuntivo, modales y comparativas, relativos con preposición, «cuyo», referentes neutros, antecedentes desconocidos y estilo indirecto.",["b2.gram.g137","b2.gram.g138","b2.gram.g139","b2.gram.g140","b2.gram.g141","b2.gram.g142","b2.gram.g143","b2.gram.g144","b2.gram.g145","b2.gram.g146"]],
  [11,"gram","g147","Cambio de deícticos: aquí/allí, hoy/ese día","Puedo contar lo que alguien dijo en otro día y en otro lugar recalculando desde mi momento y mi sitio las referencias de tiempo (hoy, mañana, ahora), de lugar (aquí, este), de persona (mi, te) y de movimiento (venir, traer), y decidir cuándo no hace falta cambiarlas.",["b2.gram.g146"],{"related":["/gramatica/cambio-de-deicticos-aqui-alli-hoy"]}],
  [11,"gram","g148","Pasiva perifrástica: ser + participio","Puedo poner en primer plano lo que recibe una acción con «ser + participio» en distintos tiempos, hacer concordar el participio, añadir el agente con «por» cuando aporta información y elegir la activa cuando la pasiva suena pesada.",["b1.gram.g119","b1.gram.g121"],{"related":["/gramatica/pasiva-impersonal-informar"]}],
  [11,"voc","w11-patrimonio-ferroviario","Patrimonio ferroviario y prensa local","Puedo hablar de la recuperación de un edificio histórico y de su cobertura en la prensa con expresiones como «poner en valor», «el acto de reapertura», «a cargo de la obra» o «citar textualmente».",["b2.gram.g148"]],
  [11,"pron","w11-terminaciones-participio","Terminaciones del participio y sinalefa en la pasiva","Puedo oír y pronunciar con claridad el género y el número del participio («restaurado», «restauradas») y unir sin pausa «fue inaugurada» o «ha sido abierto».",["b2.gram.g148"]],
  [11,"lis","w11-redaccion-reconstruye","Conversación en una redacción","Puedo seguir una conversación en la que dos periodistas reconstruyen una llamada de días atrás y recalcular qué día y qué lugar señalaba cada «mañana» y cada «aquí».",["b2.gram.g147"]],
  [11,"read","w11-noticia-reapertura","Noticia de una reapertura","Puedo leer una noticia de un diario regional, distinguir lo que se hizo de quién lo hizo y situar en el tiempo cada declaración transmitida.",["b2.gram.g147","b2.gram.g148"]],
  [11,"wri","w11-nota-boletin","Nota informativa para un boletín","Puedo escribir una nota de más de 220 palabras sobre una inauguración que combine la pasiva con «ser» y declaraciones transmitidas días después, con referencias de tiempo y lugar ajustadas.",["b2.gram.g148","b2.disc.w11-situar-declaraciones"]],
  [11,"spk","w11-transmitir-mensaje","Transmitir un mensaje de otro día y otro lugar","Puedo transmitir oralmente un encargo recibido días antes en otro sitio y aclarar con mi interlocutor qué día y qué lugar quería decir la otra persona.",["b2.fun.w11-aclarar-referencias"]],
  [11,"fun","w11-aclarar-referencias","Aclarar referencias de tiempo y lugar","Puedo pedir y dar aclaraciones cuando un «mañana», un «aquí» o un «este» de otra persona ya no sirven: «¿qué mañana: el del lunes?», «allá, en el puerto».",["b2.gram.g147"]],
  [11,"disc","w11-situar-declaraciones","Situar cada declaración en su día y su lugar","Puedo organizar un texto informativo que separa los hechos, presentados con la pasiva, de las declaraciones, cada una con su autor, su día y su lugar.",["b2.gram.g147","b2.gram.g148"]],
  [12,"gram","g149","Se pasivo, se impersonal y activo contrastados","Puedo contar el mismo hecho en activa, con «ser + participio», con «se» pasivo (el verbo concuerda con la cosa) o con «se» impersonal (siempre en singular, también con «a» + persona), y elegir la forma según el tipo de texto y la importancia del agente.",["b2.gram.g148","b1.gram.g119"],{"related":["/gramatica/se-pasivo-se-impersonal-y-activo"]}],
  [12,"gram","g150","Se accidental y responsabilidad atenuada","Puedo contar percances con «se me rompió», «se le olvidaron» o «se nos acabó», haciendo concordar el verbo con la cosa, y decidir si presento un hecho como involuntario o asumo con claridad mi responsabilidad.",["b2.gram.g149","b1.gram.g122"],{"related":["/gramatica/se-accidental-y-responsabilidad-atenuada"]}],
  [12,"voc","w12-excursion-yacimiento","Excursión, museo y trabajo de campo","Puedo hablar de una salida educativa y del trabajo en un yacimiento con expresiones como «la autorización firmada», «el yacimiento», «la campaña de excavación», «sufrir un percance» o «hacerse cargo de un error».",["b2.gram.g150"]],
  [12,"pron","w12-clitico-agrupado","Pronombres átonos agrupados","Puedo oír a quién le pasó algo en «se me», «se le» o «se nos» y pronunciar «se me cayó» como un solo grupo acentual, con la fuerza en el verbo.",["b2.gram.g150"]],
  [12,"lis","w12-informe-excursion","Repaso de una excursión para un informe","Puedo seguir una conversación en la que dos docentes repasan los percances de una salida, distinguir lo accidental de lo que fue una decisión y reconstruir el aviso para las familias.",["b2.gram.g149","b2.gram.g150"]],
  [12,"read","w12-diario-campana","Columna de una técnica de campo","Puedo leer una columna de una revista de museo que describe un trabajo con «se» pasivo e impersonal y reflexiona sobre cómo contar los propios errores.",["b2.gram.g149","b2.gram.g150"]],
  [12,"wri","w12-correo-disculpa","Correo de balance y disculpa","Puedo escribir un correo formal de más de 220 palabras que informe sobre una actividad con «se», cuente percances con el «se» accidental y asuma la responsabilidad cuando corresponde.",["b2.gram.g150","b2.disc.w12-informar-y-asumir"]],
  [12,"spk","w12-explicar-percances","Explicar percances y responder a una queja","Puedo contar un percance graduando la responsabilidad y responder a una persona molesta con explicaciones, disculpas y una propuesta de reparación.",["b2.fun.w12-disculparse-matizando"]],
  [12,"fun","w12-disculparse-matizando","Disculparse sin evadir","Puedo disculparme por un percance con «se me…» y, cuando fue una decisión mía, asumirlo en primera persona: «fue culpa mía», «me equivoqué al…».",["b2.gram.g150"]],
  [12,"disc","w12-informar-y-asumir","Informar con distancia y asumir con claridad","Puedo organizar un texto que presenta los datos de forma impersonal y, en otro párrafo, asume responsabilidades en primera persona sin mezclar los dos registros.",["b2.gram.g149","b2.gram.g150"]],
  [13,"gram","g151","Verbos que rigen preposición: confiar en, depender de","Puedo usar verbos como «depender de», «confiar en», «contar con», «darse cuenta de» o «insistir en» con un nombre, un infinitivo o una oración con «que» sin perder la preposición, también en preguntas, y distinguir verbos que cambian de sentido según la preposición.",["b1.gram.g110"],{"related":["/verbos-que-piden-una-estructura"]}],
  [13,"gram","g152","Oraciones sustantivas complejas: el hecho de que","Puedo comentar un hecho poniéndolo al principio con «el hecho de que» o «que» + subjuntivo, y elegir el modo después de sustantivos como «la posibilidad de que» o «la noticia de que», distinguiendo «la noticia que leí» de «la noticia de que ganamos».",["b2.gram.g151","b1.gram.g092"],{"related":["/gramatica/oraciones-sustantivas-complejas-el-hecho-de"]}],
  [13,"voc","w13-trabajo-hibrido","Trabajo híbrido y cambios en la empresa","Puedo hablar de cambios en la organización del trabajo con expresiones como «la jornada presencial», «trabajar en remoto», «el traslado», «plantear una inquietud» o «llegar a un acuerdo».",["b2.gram.g151"]],
  [13,"pron","w13-de-que-atono","«De que» átono y «¿de qué?» tónico","Puedo distinguir de oído la pregunta «¿de qué depende?» del enlace «depende de que…» y pronunciar «de que» sin fuerza, unido a lo que sigue.",["b2.gram.g151"]],
  [13,"lis","w13-anuncio-oficina","Conversación sobre un anuncio de la empresa","Puedo seguir una conversación entre dos compañeros que comentan un anuncio inesperado, reconstruir de qué depende cada decisión y separar los hechos de los rumores.",["b2.gram.g151","b2.gram.g152"]],
  [13,"read","w13-columna-presencialidad","Columna de opinión sobre la vuelta a la oficina","Puedo leer una columna de opinión que comenta hechos con «el hecho de que» y verbos con preposición, e identificar qué presenta la autora como dato y qué como valoración.",["b2.gram.g152"]],
  [13,"wri","w13-correo-postura","Correo con una postura ante un cambio","Puedo escribir un correo formal de más de 220 palabras que comente un cambio en el trabajo, exprese dudas y condiciones con sustantivos + «de que» y proponga un acuerdo.",["b2.gram.g152","b2.disc.w13-comentar-hechos"]],
  [13,"spk","w13-negociar-condiciones","Plantear una inquietud y negociar condiciones","Puedo explicar oralmente de qué depende mi decisión ante un cambio y negociar con mi jefe o jefa condiciones concretas.",["b2.fun.w13-plantear-inquietudes"]],
  [13,"fun","w13-plantear-inquietudes","Plantear inquietudes y retomar rumores","Puedo plantear una inquietud («me preocupa el hecho de que…»), retomar algo que se dijo («lo de que…») y pedir que se confirme un rumor.",["b2.gram.g152"]],
  [13,"disc","w13-comentar-hechos","Primero el hecho, después el comentario","Puedo organizar un párrafo argumentativo que presenta primero el hecho como tema y después lo comenta, sin confundir los datos con las posibilidades o los temores.",["b2.gram.g152"]],
  [14,"gram","g153","Oraciones causales avanzadas: no porque + subjuntivo","Puedo desmentir una causa falsa con «no porque + subjuntivo…, sino porque + indicativo» y «no por + infinitivo», suavizar una negativa con «no es que…, es que…», distinguir el alcance de la negación y elegir el conector causal (como, ya que, puesto que, dado que, debido a) según la posición y el registro.",["b1.gram.g115","b2.gram.g128"],{"related":["/gramatica/oraciones-causales-avanzadas-no-porque-subjuntivo"]}],
  [14,"gram","g154","Consecutivas de intensidad: tan, tanto, tal… que","Puedo expresar una consecuencia ligada a una intensidad con «tan + adjetivo o adverbio + que», «tanto/a/os/as + sustantivo + que», «verbo + tanto que» y «tal/tales + sustantivo + que», y distinguirla de la consecuencia simple con «así que».",["b1.gram.g116"],{"related":["/gramatica/consecuencias-tan-tanto"]}],
  [14,"voc","w14-cerros-turismo","Vivir en un cerro turístico","Puedo hablar de la vida en un barrio turístico con expresiones como «subir en ascensor», «el flujo de turistas», «encarecerse el arriendo», «el comercio de barrio» o «perder la tranquilidad».",["b2.gram.g154"]],
  [14,"pron","w14-pausa-causa","Pausa y foco en las causales","Puedo marcar con la voz la diferencia entre «No abrió, porque llovía» y «No abrió porque lloviera, sino…», y destacar «tan» o «tanto» en una consecutiva.",["b2.gram.g153"]],
  [14,"lis","w14-explicar-cierre","Conversación sobre un cambio de horario","Puedo seguir una conversación en la que una librera desmiente los motivos que le atribuyen, explica los verdaderos y cuenta las consecuencias de la llegada de turistas.",["b2.gram.g153","b2.gram.g154"]],
  [14,"read","w14-cronica-cerro","Crónica sobre un barrio turístico","Puedo leer una crónica sobre los efectos del turismo en un barrio, relacionar cada consecuencia con su causa y distinguir las causas reales de las que el autor descarta.",["b2.gram.g153","b2.gram.g154"]],
  [14,"wri","w14-carta-aclaracion","Carta que aclara una decisión","Puedo escribir una carta abierta de más de 220 palabras que desmienta una interpretación, dé la causa verdadera y explique sus consecuencias con distintos conectores.",["b2.gram.g153","b2.disc.w14-causa-consecuencia"]],
  [14,"spk","w14-desmentir-explicar","Desmentir un rumor y explicar consecuencias","Puedo desmentir oralmente un rumor sobre una decisión mía, explicar la causa real y responder a preguntas sobre sus consecuencias.",["b2.fun.w14-rechazar-interpretaciones"]],
  [14,"fun","w14-rechazar-interpretaciones","Rechazar interpretaciones con tacto","Puedo rechazar una interpretación o suavizar una negativa con «no es que…, es que…» y «no lo digo porque…, sino porque…».",["b2.gram.g153"]],
  [14,"disc","w14-causa-consecuencia","Encadenar causa, consecuencia y desmentido","Puedo organizar un texto que presenta una situación, descarta una causa, da la verdadera y encadena sus consecuencias sin repetir siempre «porque» y «así que».",["b2.gram.g153","b2.gram.g154"]],
  [15,"gram","g155","Comparativas proporcionales: cuanto más, más","Puedo decir que dos cosas cambian juntas con «cuanto más / menos…, más / menos / mejor / peor…», hacer concordar «cuanto» con un sustantivo, usar «cuanto antes» y «cuanto mayor», y elegir indicativo para lo general o pasado y subjuntivo para lo futuro o hipotético.",["b2.gram.g139"],{"related":["/gramatica/comparativas-proporcionales-cuanto-mas-mas"]}],
  [15,"gram","g156","Conectores de concesión y objeción","Puedo conceder y objetar entre oraciones y párrafos con «sin embargo», «no obstante», «aun así», «de todas formas», «ahora bien», «eso sí», «pese a» y «y eso que», puntuarlos bien y elegirlos según el registro, y usar fórmulas de debate como «tienes razón en que…, pero…».",["b2.gram.g137","b2.gram.g138","b1.gram.g114"],{"related":["/gramatica/conectores-de-concesion-y-objecion"]}],
  [15,"voc","w15-ciudad-rio","Espacio público, río y movilidad","Puedo hablar de un proyecto urbano junto a un río con expresiones como «la costanera», «la ciclovía», «el humedal», «la consulta ciudadana» o «presentar una observación».",["b2.gram.g156"]],
  [15,"pron","w15-conectores-entonacion","Pausas de los conectores y ritmo de «cuanto más»","Puedo pronunciar «sin embargo», «no obstante» o «ahora bien» con su pausa y su tono, y marcar el ritmo en dos partes de «cuanto más…, más…».",["b2.gram.g155","b2.gram.g156"]],
  [15,"lis","w15-debate-radio","Debate en una radio local","Puedo seguir un debate radial con tres voces, reconstruir qué concede y qué objeta cada participante y relacionar sus argumentos con datos y causas.",["b2.gram.g155","b2.gram.g156"]],
  [15,"read","w15-reportaje-costanera","Reportaje sobre un proyecto urbano","Puedo leer un reportaje extenso que combina datos en pasiva, declaraciones transmitidas, causas, consecuencias y concesiones, y separar los hechos de las posturas.",["b2.gram.g156"]],
  [15,"wri","w15-observacion-consulta","Observación a una consulta pública","Puedo escribir una observación formal de más de 220 palabras a una consulta pública que conceda y objete con conectores variados e integre las estructuras de las semanas 11 a 15.",["b2.gram.g156","b2.disc.w15-conceder-objetar"]],
  [15,"spk","w15-debatir-propuesta","Debatir una propuesta urbana","Puedo defender una postura en un debate oral, conceder lo razonable del otro, objetar con fórmulas adecuadas y proponer una solución intermedia.",["b2.fun.w15-conceder-matizar"]],
  [15,"fun","w15-conceder-matizar","Conceder y matizar en un debate","Puedo aceptar parte de un argumento y añadir el mío con «tienes razón en que…, pero…», «no digo que no…, pero…», «ahora bien» o «eso sí».",["b2.gram.g156"]],
  [15,"disc","w15-conceder-objetar","Párrafos que conceden y objetan","Puedo organizar un texto argumentativo en el que cada párrafo concede un punto, lo matiza con un conector y lo relaciona con una consecuencia proporcional.",["b2.gram.g155","b2.gram.g156"]],
  [15,"rev","w15-semanas-11-15","Punto de control: semanas 11 a 15","Puedo combinar en un mismo texto deícticos recalculados, pasiva con «ser», «se» pasivo, impersonal y accidental, verbos con preposición, «el hecho de que», causas desmentidas, consecutivas de intensidad, comparativas proporcionales y conectores de concesión.",["b2.gram.g147","b2.gram.g148","b2.gram.g149","b2.gram.g150","b2.gram.g151","b2.gram.g152","b2.gram.g153","b2.gram.g154","b2.gram.g155","b2.gram.g156"]],
  [16,"gram","g157","Participios y adjetivos resultativos","Puedo presentar resultados con tener, llevar y dejar + participio concordado con el objeto, contar cómo quedó algo con quedar(se), ir y andar + participio, y elegir entre participios dobles y adjetivos como «despierto» o «leído».",["b1.gram.g120","b1.gram.g121"],{"related":["/gramatica/participios-y-adjetivos-resultativos"]}],
  [16,"gram","g158","Perífrasis de obligación e inferencia","Puedo distinguir obligación y deducción con deber, deber de y tener que, usar haber de en textos formales, «haber que» impersonal en todos los tiempos y «venir a» para aproximar o resumir.",["a2.gram.g080"],{"related":["/gramatica/perifrasis-de-obligacion-e-inferencia"]}],
  [16,"voc","w16-mudanza-biblioteca","Mudanza de un espacio comunitario","Puedo hablar de una mudanza y del estado de un local con expresiones como «rotular las cajas», «desarmar las estanterías», «el flete» o «una gotera».",["b2.gram.g157"]],
  [16,"pron","w16-terminaciones-y-de","Terminaciones del participio y el «de» de «deber de»","Puedo oír y pronunciar completas las terminaciones -os/-as de los participios concordados y unir «debe de» sin pausa para que se entienda como deducción.",["b2.gram.g157","b2.gram.g158"]],
  [16,"lis","w16-dia-de-mudanza","Llamada el día de una mudanza","Puedo seguir una llamada entre dos voluntarios que hacen balance de una mudanza y separar lo hecho, lo obligatorio y lo que solo suponen sobre un problema.",["b2.gram.g157","b2.gram.g158"]],
  [16,"read","w16-diario-mudanza","Boletín de una biblioteca comunitaria","Puedo leer el boletín de una biblioteca que se muda e identificar qué está hecho, qué se suponía y qué se comprobó, y qué normas se fijaron.",["b2.gram.g157","b2.gram.g158"]],
  [16,"wri","w16-informe-estado","Informe sobre el estado de un proyecto","Puedo escribir un informe de más de 200 palabras para una asamblea que separe lo hecho, lo que está en curso, lo que deduzco de un problema y lo que hay que hacer.",["b2.gram.g157","b2.disc.w16-informe-hecho-pendiente"]],
  [16,"spk","w16-balance-y-deduccion","Hacer balance y deducir causas","Puedo hacer oralmente el balance de un proyecto largo y negociar con alguien quién tiene que resolver un problema cuya causa todavía deducimos.",["b2.fun.w16-balance-obligacion-deduccion"]],
  [16,"fun","w16-balance-obligacion-deduccion","Hacer balance, obligar y deducir","Puedo presentar lo que tengo hecho, expresar una obligación con el grado de fuerza adecuado y deducir lo que no veo graduando mi seguridad.",["b2.gram.g157","b2.gram.g158"]],
  [16,"disc","w16-informe-hecho-pendiente","Organizar un informe de estado","Puedo organizar un informe en bloques de balance, problema y tareas pendientes, marcando qué es dato comprobado y qué es suposición.",["b2.gram.g158"]],
  [17,"gram","g159","Perífrasis aspectuales avanzadas","Puedo medir una acción abierta con «llevar» + tiempo + gerundio o + «sin» + infinitivo, matizar su avance con ir, venir y andar + gerundio y ordenar sus fases con echarse a, volver a, estar a punto de, acabar + gerundio o terminar por.",["b1.gram.g106","b1.gram.g107","b1.gram.g108","b1.gram.g109"],{"related":["/gramatica/perifrasis-aspectuales-avanzadas"]}],
  [17,"gram","g160","Futuro compuesto: anterioridad y conjetura","Puedo formar el futuro compuesto y usarlo para decir qué estará terminado antes de un momento futuro, hacer balance hasta una fecha y suponer qué ha ocurrido, distinguiendo una lectura de otra por el punto de referencia.",["a2.gram.g046","a2.gram.g057"],{"related":["/sistema-verbal/futuro-compuesto-indicativo"]}],
  [17,"voc","w17-astillero","Astillero y proyecto largo","Puedo hablar de la restauración de una embarcación y del ritmo de un proyecto con expresiones como «calafatear», «botar una embarcación», «retomar un proyecto» o «cumplir un plazo».",["b2.gram.g159"]],
  [17,"pron","w17-ha-habra","«Ha» frente a «habrá» y acento del gerundio","Puedo distinguir de oído el pretérito perfecto del futuro compuesto («ha subido» / «habrá subido») y pronunciar las perífrasis de gerundio como un solo bloque.",["b2.gram.g160"]],
  [17,"lis","w17-astillero-sabado","Conversación de trabajo en un astillero","Puedo seguir una conversación entre dos carpinteros que hacen balance de una restauración y separar duraciones, previsiones con fecha y suposiciones.",["b2.gram.g159","b2.gram.g160"]],
  [17,"read","w17-cronica-lancha","Crónica sobre un proyecto comunitario","Puedo leer una crónica de un boletín cooperativo e identificar cuánto tiempo llevan con cada tarea, qué estará hecho antes de cada fecha y qué es solo una suposición.",["b2.gram.g159","b2.gram.g160"]],
  [17,"wri","w17-informe-avance","Informe de avance para financiadores","Puedo escribir un informe de más de 200 palabras que mida lo hecho, explique las dificultades y fije un calendario con futuros compuestos.",["b2.gram.g160","b2.disc.w17-cronologia-proyecto"]],
  [17,"spk","w17-proyecto-largo","Contar y defender un proyecto largo","Puedo contar oralmente un proyecto de años y negociar un calendario realista con alguien preocupado por el plazo.",["b2.fun.w17-duracion-y-plazos"]],
  [17,"fun","w17-duracion-y-plazos","Medir duraciones y anticipar plazos","Puedo decir cuánto tiempo llevo con algo, cómo va avanzando y qué habré terminado antes de una fecha, y suponer causas sin presentarlas como datos.",["b2.gram.g159","b2.gram.g160"]],
  [17,"disc","w17-cronologia-proyecto","Organizar la cronología de un proyecto","Puedo organizar un texto que va de lo hecho hasta hoy a las dificultades y al calendario futuro, con marcas temporales claras.",["b2.gram.g160"]],
  [18,"gram","g161","Futuro y condicional de probabilidad","Puedo hacer suposiciones moviendo el verbo un tiempo hacia adelante (será, habrá salido, sería, habría salido), formular preguntas de duda, conceder con «será…, pero» y distinguir la suposición de la hipótesis con «si».",["b2.gram.g160","b2.gram.g158","b1.gram.g103"],{"related":["/gramatica/futuro-y-condicional-de-probabilidad"]}],
  [18,"gram","g162","Nominalización y grupos nominales complejos","Puedo escribir grupos nominales precisos: elipsis que se recuperan sin duda, relativas restrictivas y explicativas bien puntuadas, relaciones de «de» explícitas con participios, nombres cuyo género cambia el sentido y nominalizaciones moderadas.",["b2.gram.g142","b2.gram.g144"],{"related":["/precision-grupo-nominal-adjetival"]}],
  [18,"voc","w18-archivo-museo","Archivo, museo y migración","Puedo hablar de la catalogación de objetos y de una historia de migración con expresiones como «la procedencia», «fechar un documento», «el pie de foto» o «echar raíces».",["b2.gram.g162"]],
  [18,"pron","w18-comas-relativas","Pausas de las relativas y tono de suposición","Puedo oír y producir las pausas que distinguen una relativa explicativa de una restrictiva y bajar el tono al final de una suposición.",["b2.gram.g162","b2.gram.g161"]],
  [18,"lis","w18-baul-archivo","Conversación de catalogación","Puedo seguir a dos personas que catalogan un baúl antiguo y separar lo que saben, lo que suponen y cómo corrigen sus fichas.",["b2.gram.g161","b2.gram.g162"]],
  [18,"read","w18-ficha-exposicion","Texto de sala de una exposición","Puedo leer el texto de sala de una pequeña exposición y distinguir los datos documentados de las suposiciones, fijándome en cómo se precisa cada grupo nominal.",["b2.gram.g161","b2.gram.g162"]],
  [18,"wri","w18-cartela-y-consulta","Cartela y consulta al público","Puedo escribir una cartela y una consulta de más de 200 palabras que separen datos y suposiciones con grupos nominales que no se presten a dos lecturas.",["b2.gram.g162","b2.disc.w18-texto-expositivo-preciso"]],
  [18,"spk","w18-suponer-historia","Suponer la historia de un objeto","Puedo contar oralmente la historia probable de un objeto antiguo y negociar con alguien una redacción honesta de lo que no está probado.",["b2.fun.w18-conjeturar-precisar"]],
  [18,"fun","w18-conjeturar-precisar","Conjeturar y precisar","Puedo hacer conjeturas sobre el presente y el pasado, conceder un punto y precisar a qué persona u objeto me refiero sin ambigüedad.",["b2.gram.g161","b2.gram.g162"]],
  [18,"disc","w18-texto-expositivo-preciso","Texto expositivo con grados de certeza","Puedo organizar un texto informativo que separa datos de suposiciones y usa grupos nominales y títulos nominales precisos.",["b2.gram.g162"]],
  [19,"gram","g163","Pronombres: redundancia, duplicación y foco","Puedo decidir cuándo el pronombre átono es obligatorio (complemento conocido delante, pronombre tónico), recomendable (indirecto detrás del verbo) o imposible (foco, nombre sin artículo), contrastar temas con elipsis y reconocer «le» por «les» y «se los dije».",["b1.gram.g111","b1.gram.g122"],{"related":["/gramatica/pronombres-redundancia-duplicacion-y-foco"]}],
  [19,"gram","g164","Registro: cortesía, distancia y mandato","Puedo graduar una petición desde la orden directa hasta la fórmula impersonal, usar «¿te importaría + infinitivo?» y «le agradecería que + imperfecto de subjuntivo», mandar sin imperativo y elegir el tratamiento adecuado.",["a1.gram.g021","b1.gram.g096","b1.gram.g103","b2.gram.g128"],{"related":["/gramatica/registro-cortesia-distancia-y-mandato"]}],
  [19,"voc","w19-tablado-barrio","Fiesta de barrio y convivencia vecinal","Puedo hablar de una fiesta de barrio y de la relación con los vecinos con expresiones como «armar el escenario», «moderar el volumen», «presentar una queja» o «llegar a un acuerdo».",["b2.gram.g164"]],
  [19,"pron","w19-foco-y-tono","Acento de foco y tono de cortesía","Puedo marcar con la voz la palabra destacada como foco, hacer la pausa de un tema retomado con pronombre y dar a una petición un tono amable.",["b2.gram.g163","b2.gram.g164"]],
  [19,"lis","w19-llamada-vecina","Llamada de negociación con una vecina","Puedo seguir una llamada en la que una organizadora negocia con una vecina y reconocer cómo se retoman los temas y se gradúan las peticiones.",["b2.gram.g163","b2.gram.g164"]],
  [19,"read","w19-columna-club","Columna de un club en un periódico de barrio","Puedo leer la columna de un club de barrio e identificar qué reconoce, qué pide y con qué recursos de cortesía y de foco lo hace.",["b2.gram.g163","b2.gram.g164"]],
  [19,"wri","w19-aviso-dos-registros","Un aviso en dos registros","Puedo escribir el mismo aviso de más de 200 palabras en una versión formal para vecinos y otra informal para un equipo, con pronombres y peticiones adecuados a cada una.",["b2.gram.g164","b2.disc.w19-adaptar-registro"]],
  [19,"spk","w19-pedir-con-distancia","Pedir y negociar con la distancia justa","Puedo pedir el mismo favor a personas con distinta relación y negociar con cortesía con alguien que se queja.",["b2.fun.w19-pedir-mandar-registro"]],
  [19,"fun","w19-pedir-mandar-registro","Pedir, mandar y destacar","Puedo pedir, mandar y corregir información adaptando el tratamiento, la forma verbal y el orden de las palabras a la situación.",["b2.gram.g163","b2.gram.g164"]],
  [19,"disc","w19-adaptar-registro","Adaptar un texto a otro registro","Puedo transformar un mismo contenido de un registro formal a uno informal sin perder información.",["b2.gram.g164"]],
  [20,"gram","g165","Conectores para exposición y refutación","Puedo organizar una exposición con conectores para ordenar, añadir, ejemplificar, reformular, sacar consecuencias y concluir, y refutar con «no es cierto que» + subjuntivo, «al contrario», «no…, sino», «lejos de» o «nada más lejos de la realidad», atribuyendo cada idea a su fuente.",["b1.gram.g116","b1.gram.g117","b2.gram.g153","b2.gram.g156"],{"related":["/gramatica/conectores-para-exposicion-y-refutacion"]}],
  [20,"gram","g166","Síntesis B2: debate, explicación y texto formal","Puedo elegir en cada momento la estructura B2 adecuada para opinar y negar, conceder, imaginar, informar sin agente, precisar con relativos, citar en estilo indirecto y suponer, en un debate oral o en un texto formal.",["b2.gram.g152","b2.gram.g137","b2.gram.g135","b2.gram.g146","b2.gram.g161","b2.gram.g165"],{"related":["/gramatica/sintesis-b2-debate-explicacion-y-texto"]}],
  [20,"voc","w20-ciudad-debate","Ciudad, espacio público y debate","Puedo debatir sobre cambios urbanos con expresiones como «peatonalizar una calle», «el comercio de cercanía», «someter a consulta», «rebatir un argumento» o «llegar a un consenso».",["b2.gram.g165"]],
  [20,"pron","w20-conectores-pausas","Pausas y énfasis de los conectores","Puedo marcar con pausas los conectores de orden y reformulación y dar énfasis a los de refutación para que el oyente siga el giro del argumento.",["b2.gram.g165"]],
  [20,"lis","w20-debate-radio","Debate de radio a tres voces","Puedo seguir un debate de radio entre tres personas, reconstruir la postura de cada una, sus argumentos y refutaciones, y el acuerdo final.",["b2.gram.g165","b2.gram.g166"]],
  [20,"read","w20-columna-opinion","Columna de opinión con refutación","Puedo leer una columna de opinión extensa, identificar los argumentos que refuta, cómo los atribuye y qué concede, y valorar si su postura es equilibrada.",["b2.gram.g165","b2.gram.g166"]],
  [20,"wri","w20-carta-lectores","Carta de lectores argumentativa","Puedo escribir una carta de lectores de más de 230 palabras que exponga una postura en orden, refute dos argumentos contrarios, conceda un punto y cierre con una propuesta y una petición.",["b2.gram.g166","b2.disc.w20-argumentacion-completa"]],
  [20,"spk","w20-debate-vecinal","Debatir y hacer balance","Puedo sostener un debate de cuatro minutos con alguien que defiende la postura contraria y hacer oralmente un balance organizado de mi recorrido por el nivel.",["b2.fun.w20-exponer-refutar"]],
  [20,"fun","w20-exponer-refutar","Exponer, refutar y llegar a acuerdos","Puedo exponer una postura, refutar la contraria con datos atribuidos, conceder sin perder mi tesis y proponer una salida intermedia.",["b2.gram.g165","b2.gram.g166"]],
  [20,"disc","w20-argumentacion-completa","Organizar una argumentación completa","Puedo organizar un texto argumentativo completo con tesis, argumentos, refutación con concesión y conclusión con propuesta.",["b2.gram.g165"]],
  [20,"rev","w20-semanas-16-20","Integración: semanas 16 a 20","Puedo combinar en un mismo debate o texto participios resultativos, perífrasis de obligación, inferencia y aspecto, futuro compuesto, futuro y condicional de probabilidad, grupos nominales precisos, pronombres de foco y registro, junto con los conectores de exposición y refutación.",["b2.gram.g157","b2.gram.g158","b2.gram.g159","b2.gram.g160","b2.gram.g161","b2.gram.g162","b2.gram.g163","b2.gram.g164"]],
]);
